import{_ as l,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const P=JSON.parse('{"title":"Ceph Performance Meeting 2020-06-04","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-06-04","date":"2020-06-04T00:00:00.000Z","updated":"2020-06-05T00:00:00.000Z","tags":["Ceph","性能优化","BlueStore","RocksDB","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-06-04.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-06-04.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Performance_Meeting_2020-06-04.md"};function o(n,e,s,h,u,d){return i(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li>本次会议讨论了多个新的PR和已关闭的PR。</li><li>重点讨论了BlueStore中的Ching块设备PR，特别是擦除编码期间的限流问题。</li><li>Adam提交的PR旨在防止RocksDB分片启用时写前日志大小过大。</li><li>Mudge和Ping提交的PR关于启用RocksDB的流水线写入。</li><li>讨论了使用XXHash进行CRUSH选择的问题。</li><li>更新了RocksDB到6.8.1版本，可能带来性能改进。</li><li>讨论了性能CI的进展和计划。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>BlueStore性能优化</strong></p><ul><li>讨论了优化BlueStore内存管理，特别是通过细分内存池来提升性能。</li><li>讨论了RocksDB的写前日志大小和缓冲区管理，以及可能的限流行为。</li></ul></li><li><p><strong>性能CI的进展</strong></p><ul><li>讨论了性能CI的最新进展，包括测试环境和未来的计划。</li><li>讨论了如何利用性能CI避免合并到主分支的PR对性能产生负面影响。</li></ul></li><li><p><strong>Ceph的持续改进</strong></p><ul><li>讨论了多个PR，包括性能优化、内存管理改进和Bug修复。</li><li>讨论了处理复杂PR，特别是涉及多线程和锁定的代码。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续优化BlueStore的内存管理，特别是通过细分内存池来提升性能。</li><li>继续推进性能CI的工作，确保能够及时发现和解决性能问题。</li><li>继续审查和合并相关的PR，特别是那些能够带来性能改进和Bug修复的PR。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化BlueStore的内存管理。</li><li>继续推进性能CI的工作。</li><li>继续审查和合并相关的PR。</li><li>继续讨论和优化Ceph的PR。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了Ceph的PR，包括性能优化、内存管理改进和Bug修复。</li><li>讨论了处理复杂PR，特别是涉及多线程和锁定的代码。</li><li>讨论了如何利用性能CI避免合并到主分支的PR对性能产生负面影响。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><ul><li>本次会议讨论了Ceph的多个PR，包括性能优化、内存管理改进和Bug修复。</li><li>将继续优化BlueStore的内存管理。</li><li>将继续推进性能CI的工作。</li><li>将继续审查和合并相关的PR。</li></ul>',13)])])}const p=l(r,[["render",o]]);export{P as __pageData,p as default};
